// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowLeftIcon,
  ArrowDownIcon,
  ArrowUpIcon,
  CheckIcon,
  CombineIcon,
  DropletIcon,
  FileMinusIcon,
  FileOutputIcon,
  GripVerticalIcon,
  LayoutGridIcon,
  ListOrderedIcon,
  LockKeyholeIcon,
  Minimize2Icon,
  ScanLineIcon,
  ScissorsIcon,
  SearchIcon,
  SignatureIcon,
  WrenchIcon,
  XIcon,
  type LucideIcon,
} from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CATEGORIES,
  CONTINUE,
  FILES,
  MATCHES,
  OUTPUT,
  QUERY,
  TOOL,
  TOOLS,
  TOTAL,
  TOTAL_BEFORE,
  WATERMARK,
  categoryCount,
  formatBytes,
  usedPages,
} from './script'

const ICONS: Record<string, { icon: LucideIcon; tone: string }> = {
  merge: { icon: CombineIcon, tone: '#8b5cf6' },
  split: { icon: ScissorsIcon, tone: '#d946ef' },
  'remove-pages': { icon: FileMinusIcon, tone: '#f43f5e' },
  'extract-pages': { icon: FileOutputIcon, tone: '#a855f7' },
  organize: { icon: LayoutGridIcon, tone: '#6366f1' },
  scan: { icon: ScanLineIcon, tone: '#14b8a6' },
  compress: { icon: Minimize2Icon, tone: '#10b981' },
  repair: { icon: WrenchIcon, tone: '#84cc16' },
  sign: { icon: SignatureIcon, tone: '#f43f5e' },
  watermark: { icon: DropletIcon, tone: '#0ea5e9' },
  'page-numbers': { icon: ListOrderedIcon, tone: '#6366f1' },
  protect: { icon: LockKeyholeIcon, tone: '#64748b' },
}

const SHOWN_GROUPS = ['organize', 'optimize'] as const
const RANGE_FILE = FILES.findIndex((file) => file.range)
const WATERMARK_TOOL = CONTINUE.indexOf('watermark')

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('search', { at: 0.4, ax: 0.3 })
  click('search')
  tl.to(q('search-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('search-text', QUERY, { speed: 0.07 })
  tl.to(q('groups'), { opacity: 0, duration: 0.2 }, '<0.3')
  tl.fromTo(
    q('results'),
    { opacity: 0 },
    { opacity: 1, duration: 0.25, immediateRender: false },
    '>',
  )
  CATEGORIES.forEach((category) => {
    const hits = categoryCount(MATCHES, category.id)
    tl.set(q(`chip-count-${category.id}`), { text: String(hits) }, '<')
    if (!hits) tl.to(q(`chip-${category.id}`), { opacity: 0.4, duration: 0.2 }, '<')
  })
  tl.set(q('chip-count-all'), { text: String(MATCHES.length) }, '<')
  move(`hit-${MATCHES[0].id}`, { at: '+=0.3', ax: 0.3 })
  click(`hit-${MATCHES[0].id}`)
  tl.to(q('catalog'), { opacity: 0, y: -6, duration: 0.2 }, '<0.1')
  tl.fromTo(
    q('tool-bar'),
    { opacity: 0 },
    { opacity: 1, duration: 0.2, immediateRender: false },
    '>',
  )
  tl.fromTo(
    q('merge'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '<',
  )
  tl.fromTo(
    qa('file'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.1, immediateRender: false },
    '<0.1',
  )

  step(1, '+=0.3')
  move(`range-${RANGE_FILE}`, { ax: 0.3 })
  click(`range-${RANGE_FILE}`)
  tl.to(q(`range-ph-${RANGE_FILE}`), { opacity: 0, duration: 0.1 }, '<')
  type(`range-text-${RANGE_FILE}`, FILES[RANGE_FILE].range, { speed: 0.12 })
  tl.set(q('total'), { text: `${TOTAL} pages in total` }, '>')
  tl.fromTo(
    q('total'),
    { color: '#a78bfa' },
    { color: '#8b8b96', duration: 0.8, immediateRender: false },
    '<',
  )
  move('merge-run', { at: '+=0.3' })
  click('merge-run')
  tl.to(q('merge'), { opacity: 0, duration: 0.2 }, '+=0.15')
  tl.fromTo(
    q('result'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '>',
  )
  tl.fromTo(
    qa('result-page'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.25, stagger: 0.05, immediateRender: false },
    '<0.1',
  )
  wait(0.6)

  step(2, '+=0.1')
  move(`next-${WATERMARK_TOOL}`)
  click(`next-${WATERMARK_TOOL}`)
  tl.to(q('result'), { opacity: 0, duration: 0.2 }, '<0.1')
  tl.set(q('bar-merge'), { opacity: 0 }, '<')
  tl.set(q('bar-watermark'), { opacity: 1 }, '<')
  tl.fromTo(
    q('stamp'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '>',
  )
  tl.fromTo(
    q('wm'),
    { opacity: 0, scale: 0.8 },
    {
      opacity: WATERMARK.opacity,
      scale: 1,
      duration: 0.5,
      ease: 'back.out(1.6)',
      immediateRender: false,
    },
    '<0.2',
  )
  move('stamp-run', { at: '+=0.4' })
  click('stamp-run')
  tl.fromTo(
    q('done'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '+=0.2',
  )
  cursorOut('+=0.4')
  final('+=0.1')
  wait(1.4)

  tl.set(
    [
      q('tool-bar'),
      q('merge'),
      q('result'),
      q('stamp'),
      q('results'),
      q('done'),
      q('wm'),
      q('bar-watermark'),
    ],
    { opacity: 0 },
    0,
  )
  tl.set(
    [q('catalog'), q('groups'), q('search-ph'), q(`range-ph-${RANGE_FILE}`), q('bar-merge')],
    { opacity: 1, y: 0 },
    0,
  )
  tl.set(q('total'), { text: `${TOTAL_BEFORE} pages in total` }, 0)
  tl.set(q('chip-count-all'), { text: String(TOOLS.length) }, 0)
  CATEGORIES.forEach((category) => {
    tl.set(q(`chip-count-${category.id}`), { text: String(categoryCount(TOOLS, category.id)) }, 0)
    tl.set(q(`chip-${category.id}`), { opacity: 1 }, 0)
  })
}

function Icon({ id, size = 'size-6' }: { id: string; size?: string }) {
  const entry = ICONS[id] ?? ICONS.merge
  const Glyph = entry.icon
  return (
    <span
      className={`flex shrink-0 items-center justify-center rounded-md ${size}`}
      style={{ backgroundColor: `${entry.tone}26`, color: entry.tone }}
    >
      <Glyph className="size-3" />
    </span>
  )
}

function Card({ id, dataD }: { id: string; dataD?: string }) {
  const tool = TOOL[id]
  return (
    <span
      data-d={dataD}
      className="flex items-start gap-1.5 rounded-lg border border-line bg-white/[0.03] p-1.5"
    >
      <Icon id={id} />
      <span className="min-w-0">
        <span className="block text-[9px] font-semibold leading-tight text-ink">{tool.name}</span>
        <span className="block truncate text-[7.5px] text-muted">{tool.desc}</span>
      </span>
    </span>
  )
}

function Catalog() {
  return (
    <div data-d="catalog" className="absolute inset-0 flex flex-col gap-1.5">
      <span
        data-d="search"
        className="relative flex h-6 items-center gap-1.5 rounded-lg border border-line-strong px-2 text-[9px]"
      >
        <SearchIcon className="size-3 text-muted" />
        <span data-d="search-ph" className="absolute left-6 text-muted">
          Search {TOOLS.length} PDF tools…
        </span>
        <span data-d="search-text" className="text-ink" />
      </span>
      <div className="flex gap-1">
        <span className="flex h-5 items-center gap-1 rounded-full bg-[var(--accent)] px-1.5 text-[7.5px] font-medium text-canvas">
          All <span data-d="chip-count-all">{TOOLS.length}</span>
        </span>
        {CATEGORIES.map((category) => (
          <span
            key={category.id}
            data-d={`chip-${category.id}`}
            className="flex h-5 items-center gap-1 whitespace-nowrap rounded-full border border-line px-1.5 text-[7.5px] text-muted"
          >
            {category.short}
            <span
              data-d={`chip-count-${category.id}`}
              className="rounded-full bg-white/[0.08] px-1 tabular-nums"
            >
              {categoryCount(TOOLS, category.id)}
            </span>
          </span>
        ))}
      </div>
      <div className="relative min-h-0 flex-1 overflow-hidden">
        <div data-d="groups" className="space-y-1.5">
          {SHOWN_GROUPS.map((id) => {
            const category = CATEGORIES.find((entry) => entry.id === id)!
            const tools = TOOLS.filter((tool) => tool.category === id)
            return (
              <section key={id}>
                <p className="mb-1 flex items-center gap-1.5 text-[8px] font-semibold text-muted">
                  <span className="text-ink">{category.name}</span>
                  <span className="tabular-nums">{tools.length}</span>
                  <span className="h-px flex-1 bg-line" />
                </p>
                <div className="grid grid-cols-3 gap-1">
                  {tools.map((tool) => (
                    <Card key={tool.id} id={tool.id} />
                  ))}
                </div>
              </section>
            )
          })}
        </div>
        <div
          data-d="results"
          className="absolute inset-0 grid grid-cols-3 content-start gap-1 opacity-0"
        >
          {MATCHES.map((tool) => (
            <Card key={tool.id} id={tool.id} dataD={`hit-${tool.id}`} />
          ))}
        </div>
      </div>
    </div>
  )
}

function Thumb({ tint, small = false }: { tint: string; small?: boolean }) {
  return (
    <span
      className={`flex flex-col gap-[2px] rounded-[2px] bg-white p-[3px] shadow ${small ? 'h-7 w-5' : 'h-9 w-[26px]'}`}
    >
      <span className="block h-[3px] w-2/3 rounded-full" style={{ background: tint }} />
      {[0, 1, 2].map((line) => (
        <span key={line} className="block h-[2px] w-full rounded-full bg-black/15" />
      ))}
    </span>
  )
}

const TINTS = ['#c4b5fd', '#fdba74', '#93c5fd']

function WorkspaceBar() {
  return (
    <div className="flex h-6 items-center gap-1.5 rounded-lg border border-line px-1.5 text-[8.5px]">
      <ArrowLeftIcon className="size-3 text-muted" />
      <span className="text-muted">All PDF tools</span>
      <span className="h-3 w-px bg-line" />
      <span className="relative flex h-full items-center">
        <span data-d="bar-merge" className="flex items-center gap-1 font-semibold text-ink">
          <Icon id="merge" size="size-4" /> {TOOL.merge.name}
        </span>
        <span
          data-d="bar-watermark"
          className="absolute left-0 flex items-center gap-1 whitespace-nowrap font-semibold text-ink opacity-0"
        >
          <Icon id="watermark" size="size-4" /> {TOOL.watermark.name}
        </span>
      </span>
    </div>
  )
}

function Merge() {
  return (
    <div data-d="merge" className="absolute inset-0 flex flex-col gap-1.5 opacity-0">
      <p className="text-[9.5px] font-semibold text-ink">
        {FILES.length} files{' '}
        <span className="font-normal text-muted">
          · Drag to reorder. Leave the page box empty to use every page.
        </span>
      </p>
      <ol className="space-y-1">
        {FILES.map((file, index) => (
          <li
            key={file.name}
            data-d="file"
            className="flex items-center gap-1.5 rounded-lg border border-line bg-white/[0.02] p-1"
          >
            <GripVerticalIcon className="size-3 text-muted/60" />
            <span className="w-3 text-center text-[8px] font-bold tabular-nums text-muted">
              {index + 1}
            </span>
            <Thumb tint={TINTS[index]} />
            <span className="min-w-0 flex-1">
              <span className="block truncate text-[9px] font-semibold text-ink">{file.name}</span>
              <span className="block text-[7.5px] tabular-nums text-muted">
                {file.kind === 'pdf'
                  ? `${file.pages} pages · ${formatBytes(file.bytes)}`
                  : `Image · ${file.width} × ${file.height} · ${formatBytes(file.bytes)}`}
              </span>
            </span>
            {file.kind === 'pdf' && file.pages > 1 ? (
              <span
                data-d={`range-${index}`}
                className="relative flex h-5 w-24 items-center rounded border border-line-strong px-1.5 text-[8px]"
              >
                <span data-d={`range-ph-${index}`} className="absolute left-1.5 text-muted">
                  All {file.pages} pages
                </span>
                <span data-d={`range-text-${index}`} className="font-mono text-ink" />
              </span>
            ) : null}
            <span className="flex gap-0.5 text-muted">
              <ArrowUpIcon className="size-2.5" />
              <ArrowDownIcon className="size-2.5" />
              <XIcon className="size-2.5" />
            </span>
          </li>
        ))}
      </ol>
      <p className="text-[8px] text-muted">
        File name{' '}
        <span className="ml-1 rounded border border-line px-1.5 py-px text-ink">{OUTPUT}</span> .pdf
      </p>
      <div className="mt-auto flex items-center gap-2 border-t border-line pt-1.5">
        <span
          data-d="merge-run"
          className="flex h-6 items-center gap-1 rounded-md bg-[var(--accent)] px-2.5 text-[9px] font-semibold text-canvas"
        >
          <CombineIcon className="size-3" /> Merge {FILES.length} files
        </span>
        <span data-d="total" className="ml-auto text-[8.5px] tabular-nums text-muted">
          {TOTAL_BEFORE} pages in total
        </span>
      </div>
    </div>
  )
}

const PAGE_TINTS = FILES.flatMap((file, index) =>
  Array.from({ length: usedPages(file, file.range) }, () => TINTS[index]),
)

function Result() {
  return (
    <div data-d="result" className="absolute inset-0 flex flex-col gap-2 opacity-0">
      <div className="flex items-center gap-2">
        <span className="flex size-6 items-center justify-center rounded-full bg-emerald-500 text-white">
          <CheckIcon className="size-3.5" strokeWidth={3} />
        </span>
        <span>
          <span className="block text-[10.5px] font-semibold text-ink">Your file is ready</span>
          <span className="block text-[8px] text-muted">
            {OUTPUT}.pdf · PDF · {TOTAL} pages
          </span>
        </span>
      </div>
      <div className="flex justify-center gap-1.5 rounded-lg border border-line bg-white/[0.03] p-2">
        {PAGE_TINTS.map((tint, index) => (
          <span key={index} data-d="result-page">
            <Thumb tint={tint} />
          </span>
        ))}
      </div>
      <p className="text-[8px] text-muted">Form fields and bookmarks are not carried over.</p>
      <div className="mt-auto">
        <p className="mb-1 text-[8px] font-medium text-muted">Continue with</p>
        <div className="flex flex-wrap gap-1">
          {CONTINUE.map((id, index) => (
            <span
              key={id}
              data-d={`next-${index}`}
              className="flex h-5 items-center gap-1 rounded-full border border-line pl-0.5 pr-1.5 text-[8px] text-ink"
            >
              <Icon id={id} size="size-4" /> {TOOL[id].name}
            </span>
          ))}
        </div>
      </div>
    </div>
  )
}

function Stamp() {
  const options = [
    ['Text', WATERMARK.text],
    ['Size', `${WATERMARK.fontSize} pt`],
    ['Opacity', `${Math.round(WATERMARK.opacity * 100)}%`],
    ['Angle', `${WATERMARK.angle}°`],
    ['Layout', WATERMARK.layout],
    ['Apply to', `All pages (${TOTAL})`],
  ]
  return (
    <div data-d="stamp" className="absolute inset-0 flex gap-2 opacity-0">
      <div className="flex w-[52%] flex-col gap-1">
        {options.map(([label, value]) => (
          <span
            key={label}
            className="flex items-center justify-between rounded border border-line px-1.5 py-[3px] text-[8px]"
          >
            <span className="text-muted">{label}</span>
            <span className="font-medium text-ink">{value}</span>
          </span>
        ))}
        <span
          data-d="stamp-run"
          className="mt-auto flex h-6 items-center justify-center gap-1 rounded-md bg-[var(--accent)] text-[9px] font-semibold text-canvas"
        >
          <DropletIcon className="size-3" /> Stamp {TOTAL} pages
        </span>
      </div>
      <div className="relative flex flex-1 items-center justify-center rounded-lg border border-line bg-white/[0.03]">
        <span className="relative flex h-[150px] w-[106px] flex-col gap-1 overflow-hidden rounded-sm bg-white p-2.5 shadow-lg">
          <span className="block h-1.5 w-1/2 rounded-full" style={{ background: TINTS[0] }} />
          {Array.from({ length: 9 }, (_, line) => (
            <span
              key={line}
              className="block h-[3px] rounded-full bg-black/10"
              style={{ width: `${92 - (line % 3) * 14}%` }}
            />
          ))}
          <span
            data-d="wm"
            className="absolute inset-0 flex items-center justify-center font-sans text-[15px] font-bold tracking-wide opacity-0"
            style={{ color: WATERMARK.color }}
          >
            <span style={{ transform: `rotate(${-WATERMARK.angle}deg)` }}>{WATERMARK.text}</span>
          </span>
        </span>
        <p className="absolute bottom-1 text-[7.5px] text-muted">Preview · page 1</p>
        <div
          data-d="done"
          className="absolute inset-x-2 top-2 flex items-center gap-1.5 rounded-lg border border-emerald-500/40 bg-[#101016] p-1.5 opacity-0 shadow-xl"
        >
          <span className="flex size-4 items-center justify-center rounded-full bg-emerald-500 text-white">
            <CheckIcon className="size-2.5" strokeWidth={3} />
          </span>
          <span className="min-w-0">
            <span className="block text-[8.5px] font-semibold text-ink">Your file is ready</span>
            <span className="block truncate text-[7.5px] text-muted">{OUTPUT}-watermarked.pdf</span>
          </span>
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`PDF Toolkit: searching ${TOOLS.length} tools for “${QUERY}”, merging ${FILES.length} files into ${TOTAL} pages, then adding a ${WATERMARK.text} watermark to the result`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={<span className="text-[9px] text-muted">{TOOLS.length} tools · on device</span>}
      >
        <div className="relative h-full">
          <Catalog />
          <ToolView />
        </div>
      </PanelChrome>
    </DemoStage>
  )
}

function ToolView() {
  return (
    <div className="pointer-events-none absolute inset-0 flex flex-col gap-1.5">
      <div data-d="tool-bar" className="opacity-0">
        <WorkspaceBar />
      </div>
      <div className="relative min-h-0 flex-1">
        <Merge />
        <Result />
        <Stamp />
      </div>
    </div>
  )
}
